"use strict";

var lib = (() => {
  // Helper to get the first property name of an object (used by __commonJS)
  const __getOwnPropNames = Object.getOwnPropertyNames;

  /**
   * Minimal CommonJS wrapper used by the original bundle.
   * It executes the module factory only once and caches the exports.
   *
   * @param {Object} cb   Object whose first property is the factory function.
   * @param {Object} mod  Optional pre‑filled module object.
   * @returns {Function}  A function that returns the cached `module.exports`.
   */
  const __commonJS = (cb, mod) => function __require() {
    try {
      return mod || (0, cb[__getOwnPropNames(cb)[0]])(
        (mod = { exports: {} }).exports,
        mod
      ), mod.exports;
    } catch (e) {
      // Preserve the original behaviour: clear the cache on error.
      mod = 0;
      throw e;
    }
  };

  // -------------------------------------------------------------------------
  // benchmarks/reconstruct/.cache/ms/index.js
  // -------------------------------------------------------------------------
  var require_index = __commonJS({
    "benchmarks/reconstruct/.cache/ms/index.js"(exports, module) {
      // Time constants (in milliseconds)
      const SECOND = 1e3;
      const MINUTE = SECOND * 60;
      const HOUR   = MINUTE * 60;
      const DAY    = HOUR * 24;
      const WEEK   = DAY * 7;
      const YEAR   = DAY * 365.25;

      /**
       * Main exported function.
       *
       * @param {string|number} val      Value to parse or format.
       * @param {Object} [options]       Optional configuration.
       * @param {boolean} [options.long] When true and `val` is a number,
       *                                  a long format (e.g. "2 hours") is returned.
       * @returns {number|string}        Milliseconds (if parsing) or formatted string.
       */
      module.exports = function (val, options) {
        options = options || {};
        const type = typeof val;

        if (type === "string" && val.length > 0) {
          return parse(val);
        }

        if (type === "number" && isFinite(val)) {
          return options.long ? fmtLong(val) : fmtShort(val);
        }

        throw new Error(
          "val is not a non-empty string or a valid number. val=" +
            JSON.stringify(val)
        );
      };

      /**
       * Parse a human‑readable time string into milliseconds.
       *
       * Supported units (case‑insensitive):
       *   years / yr / yrs / y
       *   weeks / w
       *   days / d
       *   hours / hr / hrs / h
       *   minutes / min / mins / m
       *   seconds / sec / secs / s
       *   milliseconds / ms / msec / msecs
       *
       * @param {string} str
       * @returns {number|undefined}
       */
      function parse(str) {
        str = String(str);
        if (str.length > 100) return undefined;

        const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(
          str
        );
        if (!match) return undefined;

        const n = parseFloat(match[1]);
        const unit = (match[2] || "ms").toLowerCase();

        switch (unit) {
          case "years":
          case "year":
          case "yrs":
          case "yr":
          case "y":
            return n * YEAR;
          case "weeks":
          case "week":
          case "w":
            return n * WEEK;
          case "days":
          case "day":
          case "d":
            return n * DAY;
          case "hours":
          case "hour":
          case "hrs":
          case "hr":
          case "h":
            return n * HOUR;
          case "minutes":
          case "minute":
          case "mins":
          case "min":
          case "m":
            return n * MINUTE;
          case "seconds":
          case "second":
          case "secs":
          case "sec":
          case "s":
            return n * SECOND;
          case "milliseconds":
          case "millisecond":
          case "msecs":
          case "msec":
          case "ms":
            return n;
          default:
            return undefined;
        }
      }

      /**
       * Short format (e.g. "2h", "5m").
       *
       * @param {number} ms
       * @returns {string}
       */
      function fmtShort(ms) {
        const msAbs = Math.abs(ms);
        if (msAbs >= DAY) return Math.round(ms / DAY) + "d";
        if (msAbs >= HOUR) return Math.round(ms / HOUR) + "h";
        if (msAbs >= MINUTE) return Math.round(ms / MINUTE) + "m";
        if (msAbs >= SECOND) return Math.round(ms / SECOND) + "s";
        return ms + "ms";
      }

      /**
       * Long format (e.g. "2 hours", "1 day").
       *
       * @param {number} ms
       * @returns {string}
       */
      function fmtLong(ms) {
        const msAbs = Math.abs(ms);
        if (msAbs >= DAY) return plural(ms, msAbs, DAY, "day");
        if (msAbs >= HOUR) return plural(ms, msAbs, HOUR, "hour");
        if (msAbs >= MINUTE) return plural(ms, msAbs, MINUTE, "minute");
        if (msAbs >= SECOND) return plural(ms, msAbs, SECOND, "second");
        return ms + " ms";
      }

      /**
       * Helper for `fmtLong` – decides whether to pluralise the unit name.
       *
       * The original library pluralises when the absolute rounded value is **not**
       * exactly 1 (i.e., 1 → singular, everything else → plural).
       *
       * @param {number} ms   Original millisecond value (may be negative).
       * @param {number} msAbs Absolute value of `ms`.
       * @param {number} n    Milliseconds per unit (e.g. `DAY`).
       * @param {string} name Singular unit name (e.g. "day").
       * @returns {string}
       */
      function plural(ms, msAbs, n, name) {
        const rounded = Math.round(ms / n);
        const isPlural = Math.abs(rounded) !== 1;
        return rounded + " " + name + (isPlural ? "s" : "");
      }
    }
  });

  // Export the module's public API.
  return require_index();
})();

/**
 * Deep‑lookup helper (dlv)
 *
 * @param {Object} obj          The object to traverse.
 * @param {string|string[]} path   Dot‑separated string or array of keys.
 * @param {*} [fallback]        Value to return when the lookup fails.
 * @returns {*}                 The found value or the fallback.
 *
 * The implementation mirrors the original minified version:
 *   - If `path` is a string it is split on “.”.
 *   - Traversal stops as soon as a segment is missing.
 *   - If the final result is `undefined` the `fallback` is returned.
 */
function dlv(obj, path, fallback) {
  const parts = typeof path === 'string' ? path.split('.') : path;
  let result = obj;

  for (const key of parts) {
    // If the current result is nullish we cannot continue.
    if (result == null) {
      result = undefined;
      break;
    }
    result = result[key];
  }

  return result === undefined ? fallback : result;
}

/**
 * HTML‑escaping helper (escapeHtml)
 *
 * @param {*} input  Anything that can be stringified.
 * @returns {string} The input with &, <, >, ", and ' escaped.
 *
 * The algorithm follows the original source line‑by‑line:
 *   1. Convert the input to a string.
 *   2. Quickly return if no escapable characters are present.
 *   3. Walk the string from the first match, appending unchanged
 *      fragments and the appropriate HTML entity for each special char.
 */
function escapeHtml(input) {
  const str = '' + input;
  const firstMatch = /["'&<>]/.exec(str);
  if (!firstMatch) return str;

  let result = '';
  let last = 0;

  // Start scanning at the index of the first escapable character.
  for (let i = firstMatch.index; i < str.length; i++) {
    let entity;
    switch (str.charCodeAt(i)) {
      case 34: // "
        entity = '&quot;';
        break;
      case 38: // &
        entity = '&amp;';
        break;
      case 39: // '
        entity = '&#39;';
        break;
      case 60: // <
        entity = '&lt;';
        break;
      case 62: // >
        entity = '&gt;';
        break;
      default:
        continue; // Not an escapable character.
    }

    // Append the substring that precedes the current special character.
    if (last !== i) {
      result += str.substring(last, i);
    }

    // Append the escaped entity and move the cursor past the character.
    result += entity;
    last = i + 1;
  }

  // Append any trailing part of the original string.
  if (last !== str.length) {
    result += str.substring(last);
  }

  return result;
}

// Export the two utilities in a CommonJS‑compatible way.
module.exports = {
  dlv,
  escapeHtml,
};

"use strict";

/**
 * Minimal implementation of the `kleur` library.
 * This file is used by the benchmark suite and mirrors the original source
 * (https://github.com/jorgebucaran/kleur) but stripped down to the essentials.
 *
 * The module exports an object `$` whose properties are functions that wrap a
 * string with ANSI escape codes for styling terminal output.  The exported
 * functions can be chained, e.g. `$.red.bold('text')`.
 *
 * The implementation respects the following environment variables:
 *
 *   - FORCE_COLOR:   forces colour output when set to a non‑zero value.
 *   - NODE_DISABLE_COLORS: disables colours when truthy.
 *   - NO_COLOR:      disables colours when defined.
 *   - TERM:          disables colours when equal to "dumb".
 *
 * Colours are only enabled when the output stream is a TTY unless forced.
 */

let FORCE_COLOR;
let NODE_DISABLE_COLORS;
let NO_COLOR;
let TERM;
let isTTY = true;

// Detect environment when running under Node.js
if (typeof process !== "undefined") {
  ({ FORCE_COLOR, NODE_DISABLE_COLORS, NO_COLOR, TERM } = process.env || {});
  isTTY = !!(process.stdout && process.stdout.isTTY);
}

/**
 * Core object that holds the enabled flag and all style functions.
 */
const $ = {
  // Enable colours only when not explicitly disabled and when the terminal
  // supports it (or when forced).
  enabled:
    !NODE_DISABLE_COLORS &&
    NO_COLOR == null &&
    TERM !== "dumb" &&
    (FORCE_COLOR != null && FORCE_COLOR !== "0" || isTTY),

  // Modifiers
  reset: init(0, 0),
  bold: init(1, 22),
  dim: init(2, 22),
  italic: init(3, 23),
  underline: init(4, 24),
  inverse: init(7, 27),
  hidden: init(8, 28),
  strikethrough: init(9, 29),

  // Foreground colours
  black: init(30, 39),
  red: init(31, 39),
  green: init(32, 39),
  yellow: init(33, 39),
  blue: init(34, 39),
  magenta: init(35, 39),
  cyan: init(36, 39),
  white: init(37, 39),
  gray: init(90, 39),
  grey: init(90, 39),

  // Background colours
  bgBlack: init(40, 49),
  bgRed: init(41, 49),
  bgGreen: init(42, 49),
  bgYellow: init(43, 49),
  bgBlue: init(44, 49),
  bgMagenta: init(45, 49),
  bgCyan: init(46, 49),
  bgWhite: init(47, 49)
};

/**
 * Apply a list of style blocks to a string, handling nested resets.
 *
 * @param {Array<{open:string, close:string, rgx:RegExp}>} arr - style blocks
 * @param {string} str - the text to style
 * @returns {string}
 */
function run(arr, str) {
  let beg = "";
  let end = "";

  for (let i = 0; i < arr.length; i++) {
    const blk = arr[i];
    beg += blk.open;
    end += blk.close;

    // If the string already contains a closing code for this block,
    // swap the order so that nesting works correctly.
    if (str.indexOf(blk.close) !== -1) {
      str = str.replace(blk.rgx, blk.close + blk.open);
    }
  }

  return beg + str + end;
}

/**
 * Create a chainable context for a set of active styles.
 *
 * @param {number[]} has   - list of opening codes already applied
 * @param {Array} keys     - list of style block objects already applied
 * @returns {object}       - a context where each style method is bound
 */
function chain(has, keys) {
  const ctx = { has, keys };

  // Bind every style function to the new context.
  ctx.reset = $.reset.bind(ctx);
  ctx.bold = $.bold.bind(ctx);
  ctx.dim = $.dim.bind(ctx);
  ctx.italic = $.italic.bind(ctx);
  ctx.underline = $.underline.bind(ctx);
  ctx.inverse = $.inverse.bind(ctx);
  ctx.hidden = $.hidden.bind(ctx);
  ctx.strikethrough = $.strikethrough.bind(ctx);
  ctx.black = $.black.bind(ctx);
  ctx.red = $.red.bind(ctx);
  ctx.green = $.green.bind(ctx);
  ctx.yellow = $.yellow.bind(ctx);
  ctx.blue = $.blue.bind(ctx);
  ctx.magenta = $.magenta.bind(ctx);
  ctx.cyan = $.cyan.bind(ctx);
  ctx.white = $.white.bind(ctx);
  ctx.gray = $.gray.bind(ctx);
  ctx.grey = $.grey.bind(ctx);
  ctx.bgBlack = $.bgBlack.bind(ctx);
  ctx.bgRed = $.bgRed.bind(ctx);
  ctx.bgGreen = $.bgGreen.bind(ctx);
  ctx.bgYellow = $.bgYellow.bind(ctx);
  ctx.bgBlue = $.bgBlue.bind(ctx);
  ctx.bgMagenta = $.bgMagenta.bind(ctx);
  ctx.bgCyan = $.bgCyan.bind(ctx);
  ctx.bgWhite = $.bgWhite.bind(ctx);

  return ctx;
}

/**
 * Initialise a style function.
 *
 * @param {number} open   - ANSI code to start the style
 * @param {number} close  - ANSI code to end the style
 * @returns {function(string=):string|object}
 */
function init(open, close) {
  const blk = {
    open: `\x1B[${open}m`,
    close: `\x1B[${close}m`,
    rgx: new RegExp(`\\x1b\\[${close}m`, "g")
  };

  /**
   * The actual style function.
   *
   * When called with a string it returns the styled string.
   * When called without arguments it returns a chainable context.
   *
   * @param {string} [txt]
   * @returns {string|object}
   */
  return function (txt) {
    // If called as a method on a chainable context (`this` is set)
    if (this !== undefined && this.has !== undefined) {
      // Record the style if it hasn't been added yet.
      if (!this.has.includes(open)) {
        this.has.push(open);
        this.keys.push(blk);
      }

      // No argument → return the context for further chaining.
      if (txt === undefined) {
        return this;
      }

      // With argument → apply accumulated styles.
      return $.enabled ? run(this.keys, String(txt)) : String(txt);
    }

    // Called as a top‑level function (no chaining)
    if (txt === undefined) {
      // Return a fresh chainable context containing only this style.
      return chain([open], [blk]);
    }

    // Direct usage: style the string immediately.
    return $.enabled ? run([blk], String(txt)) : String(txt);
  };
}

// Export the colour utility object.
module.exports = $;
